// The Windows APIs of the node_modules restore benchmark, for vhd.ps1: the virtual disk API, which
// attaches a VHDX without diskpart, the Virtual Disk Service or the storage cmdlets, and ReFS
// block cloning. The scripts job compiles it with NmbVhd.csproj, since compiling it in PowerShell
// takes over 10 seconds on a new runner.

using System;
using System.Collections.Generic;
using System.IO;
using System.Runtime.InteropServices;
using System.Text;
using System.Threading;
using System.Threading.Tasks;

public static class NmbVhd
{
	[StructLayout(LayoutKind.Sequential)]
	private struct VirtualStorageType { public uint DeviceId; public Guid VendorId; }

	// OPEN_VIRTUAL_DISK_PARAMETERS of versions 1 to 3: the union starts at offset 4
	[StructLayout(LayoutKind.Explicit, Size = 48)]
	private struct OpenParameters
	{
		[FieldOffset(0)] public uint Version;
		[FieldOffset(4)] public uint RWDepthOrGetInfoOnly;
		[FieldOffset(8)] public int ReadOnly;
		[FieldOffset(12)] public Guid ResiliencyGuid;
		[FieldOffset(28)] public Guid SnapshotId;
	}

	[StructLayout(LayoutKind.Sequential)]
	private struct AttachParameters { public uint Version; public uint Reserved; }

	// CREATE_VIRTUAL_DISK_PARAMETERS, version 2: the union starts at offset 8. Padded beyond the
	// fields of version 2, in case the API reads the size of a later version.
	[StructLayout(LayoutKind.Explicit, Size = 256)]
	private struct CreateParameters2
	{
		[FieldOffset(0)] public uint Version;
		[FieldOffset(8)] public Guid UniqueId;
		[FieldOffset(24)] public ulong MaximumSize;
		[FieldOffset(32)] public uint BlockSizeInBytes;
		[FieldOffset(36)] public uint SectorSizeInBytes;
		[FieldOffset(40)] public uint PhysicalSectorSizeInBytes;
		[FieldOffset(48)] public IntPtr ParentPath;
		[FieldOffset(56)] public IntPtr SourcePath;
		[FieldOffset(64)] public uint OpenFlags;
		[FieldOffset(68)] public uint ParentDeviceId;
		[FieldOffset(72)] public Guid ParentVendorId;
		[FieldOffset(88)] public uint SourceDeviceId;
		[FieldOffset(92)] public Guid SourceVendorId;
		[FieldOffset(108)] public Guid ResiliencyGuid;
	}

	[StructLayout(LayoutKind.Sequential)]
	private struct DuplicateExtentsData { public IntPtr FileHandle; public long SourceFileOffset; public long TargetFileOffset; public long ByteCount; }

	[DllImport("virtdisk.dll", CharSet = CharSet.Unicode)]
	private static extern uint CreateVirtualDisk(ref VirtualStorageType type, string path, uint access, IntPtr securityDescriptor, uint flags, uint providerSpecificFlags, ref CreateParameters2 parameters, IntPtr overlapped, out IntPtr handle);

	[DllImport("virtdisk.dll", CharSet = CharSet.Unicode)]
	private static extern uint OpenVirtualDisk(ref VirtualStorageType type, string path, uint access, uint flags, ref OpenParameters parameters, out IntPtr handle);

	[DllImport("virtdisk.dll", CharSet = CharSet.Unicode)]
	private static extern uint AttachVirtualDisk(IntPtr handle, IntPtr securityDescriptor, uint flags, uint providerSpecificFlags, ref AttachParameters parameters, IntPtr overlapped);

	[DllImport("virtdisk.dll", CharSet = CharSet.Unicode)]
	private static extern uint GetVirtualDiskPhysicalPath(IntPtr handle, ref uint size, StringBuilder path);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool CloseHandle(IntPtr handle);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern IntPtr FindFirstVolume(StringBuilder name, uint length);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern bool FindNextVolume(IntPtr handle, StringBuilder name, uint length);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool FindVolumeClose(IntPtr handle);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern IntPtr CreateFile(string name, uint access, uint share, IntPtr security, uint disposition, uint flags, IntPtr template);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool DeviceIoControl(IntPtr handle, uint code, IntPtr input, uint inputSize, IntPtr output, uint outputSize, out uint returned, IntPtr overlapped);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool DeviceIoControl(IntPtr handle, uint code, ref DuplicateExtentsData input, uint inputSize, IntPtr output, uint outputSize, out uint returned, IntPtr overlapped);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool GetFileSizeEx(IntPtr handle, out long size);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool SetFilePointerEx(IntPtr handle, long distance, IntPtr newPointer, uint method);

	[DllImport("kernel32.dll", SetLastError = true)]
	private static extern bool SetEndOfFile(IntPtr handle);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern bool CopyFile(string source, string target, bool failIfExists);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern bool GetDiskFreeSpace(string root, out uint sectorsPerCluster, out uint bytesPerSector, out uint freeClusters, out uint totalClusters);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern bool GetVolumePathName(string path, StringBuilder volumePath, uint length);

	[DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
	private static extern bool SetVolumeMountPoint(string mountPoint, string volumeName);

	private static readonly IntPtr Invalid = new IntPtr(-1);
	private static VirtualStorageType Vhdx => new VirtualStorageType { DeviceId = 3, VendorId = new Guid("EC984AEC-A0F9-47e9-901F-71415A66345B") };

	/// <summary>Creates an empty dynamic VHDX with the given block size.</summary>
	public static void Create(string path, ulong maximumSize, uint blockSize)
	{
		var type = Vhdx;
		var parameters = new CreateParameters2 { Version = 2, UniqueId = Guid.NewGuid(), MaximumSize = maximumSize, BlockSizeInBytes = blockSize, SectorSizeInBytes = 512, PhysicalSectorSizeInBytes = 4096 };
		// VIRTUAL_DISK_ACCESS_NONE and CREATE_VIRTUAL_DISK_FLAG_NONE, which version 2 requires for a dynamic VHDX
		uint result = CreateVirtualDisk(ref type, path, 0, IntPtr.Zero, 0, 0, ref parameters, IntPtr.Zero, out IntPtr handle);
		if (result != 0) { throw new Exception("CreateVirtualDisk failed with error " + result); }
		CloseHandle(handle);
	}

	/// <summary>
	/// Opens the VHDX with the given version of the open parameters and open flags, then attaches it
	/// for good, without a drive letter. Returns the error of OpenVirtualDisk, 0 when it attached.
	/// </summary>
	public static uint TryAttach(string path, uint version, uint openFlags, out int disk)
	{
		disk = -1;
		var type = Vhdx;
		var open = new OpenParameters { Version = version, RWDepthOrGetInfoOnly = version == 1 ? 1u : 0u };
		// Version 1 takes an access mask, VIRTUAL_DISK_ACCESS_ALL; the later versions VIRTUAL_DISK_ACCESS_NONE
		uint result = OpenVirtualDisk(ref type, path, version == 1 ? 0x003f0000u : 0u, openFlags, ref open, out IntPtr handle);
		if (result != 0) { return result; }
		try
		{
			var attach = new AttachParameters { Version = 1 };
			// ATTACH_VIRTUAL_DISK_FLAG_NO_DRIVE_LETTER | ATTACH_VIRTUAL_DISK_FLAG_PERMANENT_LIFETIME
			result = AttachVirtualDisk(handle, IntPtr.Zero, 0x2 | 0x4, 0, ref attach, IntPtr.Zero);
			if (result != 0) { throw new Exception("AttachVirtualDisk failed with error " + result); }
			uint size = 1024;
			var physical = new StringBuilder((int)size);
			result = GetVirtualDiskPhysicalPath(handle, ref size, physical);
			if (result != 0) { throw new Exception("GetVirtualDiskPhysicalPath failed with error " + result); }
			string text = physical.ToString();
			disk = int.Parse(text.Substring(text.LastIndexOf("PhysicalDrive", StringComparison.OrdinalIgnoreCase) + "PhysicalDrive".Length));
			return 0;
		}
		finally { CloseHandle(handle); }
	}

	/// <summary>Waits for the volume of the disk and returns its \\?\Volume{GUID}\ path.</summary>
	public static string WaitForVolume(int disk, int timeoutMilliseconds)
	{
		DateTime deadline = DateTime.UtcNow.AddMilliseconds(timeoutMilliseconds);
		while (true)
		{
			string volume = FindVolume(disk);
			if (volume != null) { return volume; }
			if (DateTime.UtcNow > deadline) { throw new TimeoutException("No volume on disk " + disk); }
			Thread.Sleep(25);
		}
	}

	private static string FindVolume(int disk)
	{
		var name = new StringBuilder(1024);
		IntPtr find = FindFirstVolume(name, 1024);
		if (find == Invalid) { return null; }
		try
		{
			do
			{
				string volume = name.ToString();
				IntPtr handle = CreateFile(volume.TrimEnd('\\'), 0, 3, IntPtr.Zero, 3, 0, IntPtr.Zero);
				if (handle == Invalid) { continue; }
				IntPtr buffer = Marshal.AllocHGlobal(1024);
				try
				{
					// IOCTL_VOLUME_GET_VOLUME_DISK_EXTENTS returns VOLUME_DISK_EXTENTS, whose DISK_EXTENTs of 24 bytes start at offset 8
					if (DeviceIoControl(handle, 0x00560000, IntPtr.Zero, 0, buffer, 1024, out uint returned, IntPtr.Zero))
					{
						int count = Marshal.ReadInt32(buffer);
						for (int i = 0; i < count; i++)
						{
							if (Marshal.ReadInt32(buffer, 8 + i * 24) == disk) { return volume; }
						}
					}
				}
				finally
				{
					Marshal.FreeHGlobal(buffer);
					CloseHandle(handle);
				}
			} while (FindNextVolume(find, name, 1024));
		}
		finally { FindVolumeClose(find); }
		return null;
	}

	public static void Mount(string folder, string volume)
	{
		if (!SetVolumeMountPoint(folder, volume)) { throw new Exception("SetVolumeMountPoint failed with error " + Marshal.GetLastWin32Error()); }
	}

	/// <summary>
	/// Makes each copy of a list of "original TAB copy" lines share the blocks of its original with
	/// FSCTL_DUPLICATE_EXTENTS_TO_FILE, which ReFS supports in cluster-aligned ranges of under 4 GB,
	/// and copies the files whose clone fails. Returns a summary.
	/// </summary>
	public static string CloneFiles(string listPath, int parallelism)
	{
		var pairs = new List<string[]>();
		foreach (string line in File.ReadAllLines(listPath))
		{
			if (line.Length > 0) { pairs.Add(line.Split('\t')); }
		}
		if (pairs.Count == 0) { return "0 clones"; }
		var root = new StringBuilder(1024);
		if (!GetVolumePathName(pairs[0][0], root, 1024)) { throw new Exception("GetVolumePathName failed with error " + Marshal.GetLastWin32Error()); }
		if (!GetDiskFreeSpace(root.ToString(), out uint sectorsPerCluster, out uint bytesPerSector, out _, out _)) { throw new Exception("GetDiskFreeSpace failed with error " + Marshal.GetLastWin32Error()); }
		long cluster = (long)sectorsPerCluster * bytesPerSector;
		int cloned = 0;
		int copied = 0;
		long clonedBytes = 0;
		string firstError = null;
		Parallel.ForEach(pairs, new ParallelOptions { MaxDegreeOfParallelism = parallelism }, pair =>
		{
			string error = Clone(pair[0], pair[1], cluster, out long bytes);
			if (error == null)
			{
				Interlocked.Increment(ref cloned);
				Interlocked.Add(ref clonedBytes, bytes);
				return;
			}
			Interlocked.CompareExchange(ref firstError, pair[1] + ": " + error, null);
			if (!CopyFile(pair[0], pair[1], false)) { throw new Exception("CopyFile failed with error " + Marshal.GetLastWin32Error() + " for " + pair[1]); }
			Interlocked.Increment(ref copied);
		});
		return string.Format("{0} clones of {1:N2} GB in clusters of {2} bytes, {3} copies{4}", cloned, clonedBytes / 1e9, cluster, copied, firstError != null ? " (first failure: " + firstError + ")" : "");
	}

	private static string Clone(string original, string copy, long cluster, out long size)
	{
		size = 0;
		// GENERIC_READ, FILE_SHARE_READ, OPEN_EXISTING
		IntPtr source = CreateFile(original, 0x80000000, 1, IntPtr.Zero, 3, 0, IntPtr.Zero);
		if (source == Invalid) { return "open " + Marshal.GetLastWin32Error(); }
		try
		{
			if (!GetFileSizeEx(source, out size)) { return "size " + Marshal.GetLastWin32Error(); }
			// GENERIC_READ | GENERIC_WRITE, CREATE_ALWAYS
			IntPtr target = CreateFile(copy, 0xC0000000, 0, IntPtr.Zero, 2, 0x80, IntPtr.Zero);
			if (target == Invalid) { return "create " + Marshal.GetLastWin32Error(); }
			try
			{
				if (!SetFilePointerEx(target, size, IntPtr.Zero, 0) || !SetEndOfFile(target)) { return "set size " + Marshal.GetLastWin32Error(); }
				// The last range ends at the cluster after the end of the file
				long end = (size + cluster - 1) / cluster * cluster;
				const long chunk = 1L << 30;
				for (long offset = 0; offset < end; offset += chunk)
				{
					var data = new DuplicateExtentsData { FileHandle = source, SourceFileOffset = offset, TargetFileOffset = offset, ByteCount = Math.Min(chunk, end - offset) };
					// FSCTL_DUPLICATE_EXTENTS_TO_FILE
					if (!DeviceIoControl(target, 0x00098344, ref data, (uint)Marshal.SizeOf<DuplicateExtentsData>(), IntPtr.Zero, 0, out _, IntPtr.Zero))
					{
						return "clone " + Marshal.GetLastWin32Error();
					}
				}
				return null;
			}
			finally { CloseHandle(target); }
		}
		finally { CloseHandle(source); }
	}
}
